// Подключаем датчик пульса к аналоговому входу A0
const int sensorPin = A0;

// Зуммер (или светодиод) подключён к цифровому пину D9 через макетку
const int buzzerPin = 9; // Или pin LED на твоей схеме

void setup() {
  Serial.begin(9600);   // Для отладки: смотри показания в мониторе порта
  pinMode(buzzerPin, OUTPUT);
}

void loop() {
  int value = analogRead(sensorPin); // Считываем напряжение с датчика

  // Твой порог чувствительности. Меняй число!
  if (value > 500) {  
    digitalWrite(buzzerPin, HIGH); // Пищим или включаем свет
  } else {
    digitalWrite(buzzerPin, LOW);
  }

  delay(100);          // Небольшая пауза для стабильности
}
